"""The Law School Learning Foundation curriculum: kindergarten to law school and the bar exam.
K-12 courses are reused from the Med School Learning Foundation (same lessons), with law-oriented notes.
Writes work/courses_raw.json (writer-facing) and work/meta.json (site-facing extras)."""
import json, copy

MED_RAW = {c['code']: c for c in json.load(open('/home/claude/med/work/courses_raw.json'))}

STAGES = [
    ('K', 'Elementary school (K–5)', 'Numbers, reading and writing, science and the world around us, learned with a grown-up close by.'),
    ('J', 'Middle school (6–8)', 'Ratios to algebra, reading for evidence and argument, the sciences, and history and geography.'),
    ('H', 'High school (9–12)', 'Algebra through statistics, the lab sciences, English and rhetoric, and U.S. and world history and government.'),
    ('C', 'College pre-law', 'Writing, logic, philosophy, government, economics, statistics, accounting, legal history, speaking and the LSAT.'),
    ('L', 'Law school: first year', 'Contracts, torts, civil procedure, property, criminal law, constitutional structure, legislation and regulation, and legal research and writing.'),
    ('U', 'Law school: upper level', 'Evidence, criminal procedure, professional responsibility, business, estates, family, tax, administrative, commercial, remedies, individual rights and intellectual property, plus advocacy and practice skills.'),
    ('B', 'Bar exam preparation', 'Integrated review for the multiple-choice, essay and performance-test parts of the bar exam, including the NextGen bar exam.'),
]
LEVEL = {'K': 'elementary', 'J': 'middle', 'H': 'high', 'C': 'college', 'L': 'law', 'U': 'law', 'B': 'bar'}
FINAL_MIN = {'elementary': 30, 'middle': 45, 'high': 60, 'college': 120, 'law': 180, 'bar': 180}
HOURS = {'elementary': '2–3', 'middle': '3–4', 'high': '4–6', 'college': '8–12', 'law': '12–15', 'bar': '15–20'}

COURSES = []

def C(code, title, profile, req, soft, purpose, why, ready, reading, units, project, elective=False):
    assert len(units) == 6, code
    assert 'Week 7 midterm' in units[3][2], code
    lvl = LEVEL[code[0]]
    fm = FINAL_MIN[lvl]
    u = []
    for i, (a, b, d) in enumerate(units):
        u.append({'weeks': [2 * i + 1, 2 * i + 2], 'topics': [a, b], 'deliverable': d})
    u.append({'weeks': [13, 14], 'topics': ['Project and review', 'Cumulative final'],
              'deliverable': f'Submit the project; take an unseen {fm} minute final in week 14.'})
    completion = 'finish the project, take the week 7 midterm and week 14 cumulative final, then complete a new cumulative assessment after 1 to 2 weeks. Explain one major idea aloud without notes.'
    COURSES.append({'code': code, 'title': title, 'stage': code[0], 'level': lvl, 'profile': profile, 'req': req, 'soft': soft,
                    'prerequisites': (', '.join(req) if req else 'None') + ('; helpful: ' + ', '.join(soft) if soft else '') + '.',
                    'purpose': purpose, 'why': why, 'ready': ready,
                    'reading': {'title': reading[0], 'url': reading[1]}, 'readingScope': None, 'readingNote': None,
                    'units': u, 'project': project, 'completion': completion, 'supplement': None, 'elective': elective})

# ---------------- K-12: reused from the Med School Learning Foundation ----------------
WHY = {
    'K1': 'Number sense is the base of every later calculation, from budgets to damages.',
    'K2': 'Multiplication, fractions and measurement come back in every budget, contract and damages calculation.',
    'K3': 'Fractions, decimals and percents are the language of interest, shares and damages.',
    'K4': 'Reading is how you will learn everything else on this path.',
    'K5': 'Fluent reading and clear paragraphs make every later textbook, brief and argument possible.',
    'K6': 'Inference, word roots and research writing grow into the close reading of cases and statutes.',
    'K7': 'Careful observation and describing exactly what you see are the first skills of finding facts.',
    'K8': 'Science teaches how to test a claim against evidence, a habit every lawyer needs.',
    'K9': 'Rules, communities and government are where law begins.',
    'J1': 'Ratios, rates and percents are the arithmetic of interest, damages and statistics.',
    'J2': 'Proportional reasoning and probability underlie damages, risk and statistical evidence.',
    'J3': 'Functions and linear models help you read data and economic arguments.',
    'J4': 'Evaluating evidence and writing clear arguments is the core of legal reasoning.',
    'J5': 'Reasoning about evidence and causes prepares you for expert testimony and proof.',
    'J6': 'Physical science builds the reasoning behind accident reconstruction and expert evidence.',
    'J7': 'Earth and environmental science underlie environmental, land-use and disaster law.',
    'J8': 'History explains where laws, rights and institutions came from.',
    'H1': 'Algebra is the tool behind every financial, tax and damages calculation.',
    'H2': 'Geometric proof trains the step-by-step reasoning that legal argument uses.',
    'H3': 'Trigonometry rounds out college-preparatory mathematics and supports physics and accident reconstruction.',
    'H4': 'Precalculus models growth, decay and compound interest, the mathematics of finance.',
    'H5': 'Calculus describes rates of change and optimization in economics; for a law path it is an elective.',
    'H6': 'Statistics is how courts and agencies weigh evidence from studies and data.',
    'H7': 'Biology underlies health, environmental and food law and much expert evidence.',
    'H8': 'Chemistry underlies forensic, environmental and product-safety evidence.',
    'H9': 'Physics underlies accident reconstruction, engineering and patent disputes.',
    'H10': 'Close reading and structured writing prepare you for the LSAT and for legal writing.',
    'H11': 'Rhetoric, research and synthesis are the daily tools of lawyers.',
    'H12': 'Constitutional law, civil rights and government institutions grow out of this history.',
    'H13': 'Comparative and international law begin with understanding the world\'s histories and systems.',
}
for code, why in WHY.items():
    t = copy.deepcopy(MED_RAW[code])
    t['why'] = why
    t['reusedFrom'] = 'med:' + code
    t['elective'] = code in ('H5',)
    COURSES.append(t)

